INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q179288', 'Battle of Kosovo', 'The Battle of Kosovo took place on 15 June 1389 between an army led by the Serbian Prince Lazar Hrebeljanović and an invading army of the Ottoman Empire under the command of Sultan Murad I. It was one of the largest battles of the Late Middle Ages. The battle was fought on the Kosovo field in the territory ruled by Serbian nobleman Vuk Branković, in what is today Kosovo, about 5 kilometers (3.1 mi) northwest of the modern city of Pristina.', 1389, 6, 28, NULL, NULL, NULL, 'day', '28 June 1389', 78, 'https://en.wikipedia.org/wiki/Battle_of_Kosovo'),
  ('Q12756961', 'Siege of Novo Brdo', 'The siege of Novo Brdo was a military blockade of Novo Brdo, an important fortified mining town in the Serbian Despotate, by the forces of the Ottoman Empire. The siege began in 1440 and lasted until the capture of the fortress on 27 June 1441.', 1440, 10, NULL, 1441, 6, 27, 'month', 'October 1440 – 27 June 1441', 34, 'https://en.wikipedia.org/wiki/Siege_of_Novo_Brdo_(1440%E2%80%931441)'),
  ('Q23018766', '1901 massacres of Serbs', 'The Principality of Serbia received autonomy from the Ottoman Empire in the early 19th century, but a notable Serb population remained to the south, outside of the borders of the principality. With the Serbian–Ottoman Wars (1876–1878) and the Congress of Berlin, the Serbian borders were expanded.', 1901, 5, NULL, NULL, NULL, NULL, 'month', 'May 1901', 34, 'https://en.wikipedia.org/wiki/Violence_against_Serbs_during_the_late_Ottoman_era'),
  ('Q3438672', 'Likoshane and Qirez massacre', 'The Attacks on Likošane and Ćirez (Albanian: Sulmet në Likoshan dhe Çirez, Serbian: Napadi na Likošane i Ćirez) were large-scale police attacks that took place at the onset of the Kosovo War in the villages of Likošane and Ćirez. On 28 February 1998, the Kosovo Liberation Army (KLA) ambushed a unit of the Serbian police near Likošane, killing four and seriously wounding two policemen.', 1998, 3, 1, NULL, NULL, NULL, 'day', '1 March 1998', 37, 'https://en.wikipedia.org/wiki/Attacks_on_Liko%C5%A1ane_and_%C4%86irez'),
  ('Q10546229', 'Klečka killings', 'Crimes were allegedly committed in July 1998 near the village of Klečka, in central Kosovo, during the Kosovo War. Serbian authorities made unsubstantiated claims that mass killings were perpetrated by members of the Kosovo Liberation Army (KLA) against Serb civilians.', 1998, 7, NULL, NULL, NULL, NULL, 'month', 'July 1998', 41, 'https://en.wikipedia.org/wiki/Klecka_case'),
  ('Q1463237', 'Račak massacre', 'The Račak massacre (Albanian: Masakra e Reçakut) or Račak operation (Serbian: Акција Рачак/Akcija Račak) was the massacre of 45 Kosovo Albanian civilians that took place in the village of Račak (Albanian: Reçak) in central Kosovo in January 1999. The massacre was perpetrated by Serbian security forces in response to Albanian separatist activity in the region.', 1999, 1, 15, NULL, NULL, NULL, 'day', '15 January 1999', 56, 'https://en.wikipedia.org/wiki/Ra%C4%8Dak_massacre'),
  ('Q2759439', 'Staro Gračko massacre', 'The Staro Gracko massacre (Serbian: Масакр у Старом Грацком, Albanian: Masakra në Grackën e Vjetër) was the mass killing of 14 Kosovo Serb farmers in the village of Staro Gracko in the Kosovo municipality of Lipjan on 23 July 1999. The killings occurred after Yugoslav troops withdrew from the region in the aftermath of the Kosovo War.', 1999, 7, 23, NULL, NULL, NULL, 'day', '23 July 1999', 37, 'https://en.wikipedia.org/wiki/Staro_Gracko_massacre'),
  ('Q3271831', 'Suva Reka massacre', 'The Suva Reka massacre (Albanian: Masakra e Suharekës, Serbian: Masakr u Suvoj Reci) refers to the mass murder of Kosovo Albanian civilians committed by Serbian police officers on 26 March 1999 in Suva Reka, Kosovo, during the 1999 NATO bombings of Yugoslavia.', 1999, 3, 26, NULL, NULL, NULL, 'day', '26 March 1999', 47, 'https://en.wikipedia.org/wiki/Suva_Reka_massacre'),
  ('Q3434323', 'Izbica massacre', 'The Izbica massacre (Albanian: Masakra e Izbicës; Serbian: Pokolj u Izbici) was one of the largest massacres of the Kosovo War. Following the war, the International Criminal Tribunal for the former Yugoslavia (ICTY) found that the massacre resulted in the deaths of at least 93 Kosovar Albanians, mostly male non-combatant civilians between the ages of 60 and 70.', 1999, 3, 28, NULL, NULL, NULL, 'day', '28 March 1999', 47, 'https://en.wikipedia.org/wiki/Izbica_massacre'),
  ('Q3438679', 'Velika Kruša massacre', 'The Krusha massacres (Albanian: Masakra e Krushës së Madhe dhe Krushës së Vogël, Serbian: Масакр у Великој и Малој Круши, romanized: Masakr u Velikoj i Maloj Kruši) were two massacres that took place during the Kosovo War on the afternoon of 25 March 1999, the day after the NATO bombing of Yugoslavia began, near Orahovac, Kosovo. At that time, witnesses reported that on 25 March special police unit entered the village of Velika Kruša and separated the men and boys, and killed around 100 men and male teenagers over the age of 13.', 1999, 3, 25, NULL, NULL, NULL, 'day', '25 March 1999', 43, 'https://en.wikipedia.org/wiki/Krusha_massacres'),
  ('Q7207166', 'Podujevo massacre', 'The Podujevo massacre (Albanian: Masakra e Podujevës; Serbian: Masakr u Podujevu) is the name generally used to refer to the killing of 14 Kosovo Albanian civilians, mostly women and children, committed in March 1999 by the Scorpions, a Serbian paramilitary organisation in conjunction with the Special Anti-Terrorist Unit of Serbia, during the Kosovo War. One of the survivors of this massacre, Saranda Bogujevci, 13 years old when it occurred, received mass media attention after she successfully managed to bring to justice her case with the help of several organizations from Serbia, Canada,…', 1999, 3, 28, NULL, NULL, NULL, 'day', '28 March 1999', 41, 'https://en.wikipedia.org/wiki/Podujevo_massacre'),
  ('Q7943742', 'Vushtrri massacre', 'The Vushtrri massacre (Albanian: Masakra e Vushtrrisë) was the mass killing of 100 to 120 Kosovo Albanian refugees during the Kosovo War on the 2nd and 3rd of May 1999 near Vushtrri, Kosovo.', 1999, 5, 3, NULL, NULL, NULL, 'day', '3 May 1999', 39, 'https://en.wikipedia.org/wiki/Vushtrri_massacre'),
  ('Q861510', '2008 Kosovo declaration of independence', 'The 2008 Kosovo declaration of independence, which proclaimed the Republic of Kosovo to be an independent and sovereign state, was adopted at a meeting held on 17 February 2008 by 109 out of the 120 members of the Assembly of Kosovo, including the Prime Minister of Kosovo, Hashim Thaçi, and by the President of Kosovo, Fatmir Sejdiu (who was not a member of the Assembly). It was the second declaration of independence by Kosovo''s Albanian-majority political institutions; the first was proclaimed on 7 September 1990.', 2008, 2, 17, NULL, NULL, NULL, 'day', '17 February 2008', 71, 'https://en.wikipedia.org/wiki/2008_Kosovo_declaration_of_independence'),
  ('Q4393797', '2012 North Kosovo referendum', 'An advisory referendum on accepting the institutions of the Republic of Kosovo was held in the Serb-dominated regions of North Kosovo on 14 and 15 February 2012. The referendum was held in Zubin Potok, Zvečan and Mitrovica on both days, while Leposavić voted on 15 February.', 2012, 2, 15, NULL, NULL, NULL, 'day', '15 February 2012', 41, 'https://en.wikipedia.org/wiki/2012_North_Kosovo_referendum'),
  ('Q63078193', 'Regional Roaming Agreement', 'The Regional Roaming Agreement, formally the Agreement on the price reduction of the roaming services in public mobile communications networks in the Western Balkans region, regulates the imposition of roaming charges within the countries in the Western Balkans; Albania, Kosovo, Bosnia and Herzegovina, North Macedonia, Montenegro and Serbia. The agreement covers both the charges mobile network operators can impose on their subscribers for using telephone and data services outside of the network''s member state, and the wholesale rates networks can charge each other to allow their subscribers…', 2019, 4, 4, NULL, NULL, NULL, 'day', '4 April 2019', 41, 'https://en.wikipedia.org/wiki/Regional_Roaming_Agreement'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q113369056', 'North Kosovo crisis', 'The North Kosovo Crisis is an ongoing crisis that began on 31 July 2022, tensions between Kosovo and Serbia heightened due to the expiration of the eleven-year validity period of documents for cars on 1 August 2022, between the government of Kosovo and the Serbs in North Kosovo. Kosovo, which declared independence in 2008, signed an agreement with Serbia in 2011 that determined the use of license plates in North Kosovo.', 2022, 7, 31, NULL, NULL, NULL, 'day', '31 July 2022', 59, 'https://en.wikipedia.org/wiki/North_Kosovo_crisis_(2022%E2%80%932026)');
